// Validate and format contract_id
// Webhook POST data can be in different locations
const input = $input.all()[0].json;
const contractId = input.contract_id || input.body?.contract_id || input.query?.contract_id || (input.body && typeof input.body === 'string' ? JSON.parse(input.body).contract_id : null);

console.log('Webhook input:', JSON.stringify(input, null, 2));
console.log('Extracted contract_id:', contractId);

if (!contractId || contractId === '' || contractId === 'null' || contractId === null || contractId === undefined) {
  throw new Error('contract_id is required and cannot be empty. Received: ' + JSON.stringify(input));
}

return {
  json: {
    contract_id: String(contractId).trim()
  }
};

// Return error response if contract not found
const contractId = $node['Validate Contract ID'].json.contract_id;

return {
  json: {
    success: false,
    message: `Contract with ID ${contractId} not found. Please verify the contract exists in the database.`,
    contract_id: contractId,
    error: 'CONTRACT_NOT_FOUND'
  }
};

// Format data for approval workflow insert
// Ensure all required fields have values
// Handle foreign key constraints - only set user IDs if they are valid (not 0, null, or undefined)
const contract = $json;

// Helper function to validate user ID
function getValidUserId(...ids) {
  for (const id of ids) {
    if (id !== null && id !== undefined && id !== 0 && id !== '0' && id !== '') {
      const numId = Number(id);
      if (!isNaN(numId) && numId > 0) {
        return numId;
      }
    }
  }
  return null; // Return null instead of 0 for foreign key
}

const userId = getValidUserId(contract.creator_id, contract.created_by_id);

return {
  json: {
    document_type: 'contract',
    document_id: contract.id,
    workflow_name: `Contract Approval - ${contract.contract_number || 'N/A'}`,
    total_steps: 2,
    created_by_id: userId,
    assigned_to_id: userId,
    status: 'in_progress',
    // Keep original data for next nodes
    contract_id: contract.id,
    contract_number: contract.contract_number,
    creator_id: contract.creator_id || contract.created_by_id || null,
    creator_name: contract.creator_name,
    creator_email: contract.creator_email,
    total_amount: contract.total_amount
  }
};

// Format data for approval workflow insert
// Get total_steps dynamically from workflow_levels
// Ensure all required fields have values
// Handle foreign key constraints - only set user IDs if they are valid (not 0, null, or undefined)
const contract = $node['Get Contract Details'].json || {};
const workflowLevels = $node['Get Workflow Levels'].json || [];

// Helper function to validate user ID
function getValidUserId(...ids) {
  for (const id of ids) {
    if (id !== null && id !== undefined && id !== 0 && id !== '0' && id !== '') {
      const numId = Number(id);
      if (!isNaN(numId) && numId > 0) {
        return numId;
      }
    }
  }
  return null; // Return null instead of 0 for foreign key
}

const userId = getValidUserId(contract.creator_id, contract.created_by_id);

// Get total_steps from workflow_levels (dynamic)
const totalSteps = Array.isArray(workflowLevels) ? workflowLevels.length : 0;

// Get first level info
const firstLevel = Array.isArray(workflowLevels) && workflowLevels.length > 0 ? workflowLevels[0] : null;

return {
  json: {
    document_type: 'contract',
    document_id: contract.id,
    workflow_name: `Contract Approval - ${contract.contract_number || 'N/A'}`,
    total_steps: totalSteps || 1, // Default to 1 if no levels found
    current_step: 1, // Always start at step 1
    created_by_id: userId,
    assigned_to_id: userId,
    status: 'in_progress',
    // Keep original data for next nodes
    contract_id: contract.id,
    contract_number: contract.contract_number,
    creator_id: contract.creator_id || contract.created_by_id || null,
    creator_name: contract.creator_name,
    creator_email: contract.creator_email,
    total_amount: contract.total_amount,
    // Workflow levels data
    workflow_levels: workflowLevels,
    current_level: firstLevel,
    current_level_number: firstLevel ? firstLevel.level_number : 1,
    current_level_role: firstLevel ? firstLevel.role_id : null,
    current_level_name: firstLevel ? firstLevel.level_name : 'Level 1'
  }
};

// No approver found - return error response
const contractDetails = $node['Get Contract Details'].json || {};

return {
  json: {
    success: false,
    message: 'No approver found. Please create a user with role: manager, truong_ban_thu_ky, or pho_chu_nhiem',
    contract_id: contractDetails.id || contractDetails.contract_id,
    contract_number: contractDetails.contract_number || 'N/A',
    error: 'NO_APPROVER_FOUND'
  }
};

// Generate unique approval token
// Use level info from workflow_levels
const crypto = require('crypto');
const token = crypto.randomBytes(32).toString('hex');

// Get level info from Format Approval Data
const levelData = $node['Format Approval Data'].json || {};
const currentLevel = levelData.current_level || {};
const timeoutHours = currentLevel.timeout_hours || 48; // Default 48 hours

const expiryDate = new Date();
expiryDate.setHours(expiryDate.getHours() + timeoutHours);

return {
  json: {
    approval_token: token,
    expiry_date: expiryDate.toISOString(),
    workflow_id: $node['Create Approval Workflow'].json.id,
    contract_id: $node['Get Contract Details'].json.id || $node['Get Contract Details'].json.contract_id,
    contract_number: $node['Get Contract Details'].json.contract_number,
    approver_id: $json.id,
    approver_email: $json.email,
    approver_name: $json.full_name,
    approver_role: $json.role,
    creator_name: $node['Get Contract Details'].json.creator_name,
    creator_email: $node['Get Contract Details'].json.creator_email,
    total_amount: $node['Get Contract Details'].json.total_amount,
    level: levelData.current_level_number || 1,
    level_name: levelData.current_level_name || 'Level 1',
    timeout_hours: timeoutHours
  }
};

// Format response data from reliable nodes
// Get data from nodes that should always succeed
// Handle both success and error cases
const contractDetails = $node['Get Contract Details']?.json || {};
const approvalToken = $node['Generate Approval Token']?.json || {};
const noApproverError = $node['No Approver Error']?.json;
const contractNotFoundError = $node['Contract Not Found Error']?.json;

// If there's an error, return it (prioritize contract not found)
if (contractNotFoundError) {
  return { json: contractNotFoundError };
}

if (noApproverError) {
  return { json: noApproverError };
}

// Success case
return {
  json: {
    success: true,
    message: 'Contract approval request sent to Level 1 approver',
    contract_id: contractDetails.id || contractDetails.contract_id,
    contract_number: contractDetails.contract_number || 'N/A',
    approver: approvalToken.approver_name || 'Manager',
    workflow_id: $node['Create Approval Workflow']?.json?.id || null,
    approval_token: approvalToken.approval_token || null
  }
};

// Progress to next level
// Get workflow and next level info
const workflowData = $json[0] || {};
const currentStep = workflowData.current_step || 1;
const nextStep = currentStep + 1;
const nextLevel = {
  level_number: workflowData.next_level_number,
  level_name: workflowData.next_level_name,
  role_id: workflowData.next_role_id,
  timeout_hours: workflowData.next_timeout_hours || 48
};

return {
  json: {
    workflow_id: workflowData.id,
    document_id: workflowData.document_id,
    current_step: currentStep,
    next_step: nextStep,
    next_level: nextLevel,
    has_next_level: true
  }
};

// Generate token for next level
const crypto = require('crypto');
const token = crypto.randomBytes(32).toString('hex');
const nextLevel = $json.next_level || {};
const timeoutHours = nextLevel.timeout_hours || 48;

const expiryDate = new Date();
expiryDate.setHours(expiryDate.getHours() + timeoutHours);

const approver = $node['Get Next Level Approver'].json[0] || {};

return {
  json: {
    approval_token: token,
    expiry_date: expiryDate.toISOString(),
    workflow_id: $json.workflow_id,
    document_id: $json.document_id,
    step_number: $json.next_step,
    approver_id: approver.id,
    approver_email: approver.email,
    approver_name: approver.full_name,
    approver_role: approver.role,
    level_number: nextLevel.level_number,
    level_name: nextLevel.level_name,
    timeout_hours: timeoutHours
  }
};
